add_action( 'wp_login', 'perfectpixel_record_last_login', 10, 2 );
add_filter( 'manage_users_columns', 'perfectpixel_last_login_column' );
add_filter( 'manage_users_custom_column', 'perfectpixel_last_login_column_value', 10, 3 );
add_filter( 'manage_users_sortable_columns', 'perfectpixel_last_login_sortable' );
add_action( 'pre_get_users', 'perfectpixel_last_login_orderby' );

function perfectpixel_record_last_login( $login, $user ) {
	update_user_meta( $user->ID, 'perfectpixel_last_login', time() );
}

function perfectpixel_last_login_column( $columns ) {
	$columns['perfectpixel_last_login'] = 'Τελευταία σύνδεση';
	return $columns;
}

function perfectpixel_last_login_column_value( $value, $column, $user_id ) {
	if ( 'perfectpixel_last_login' !== $column ) {
		return $value;
	}
	$time = (int) get_user_meta( $user_id, 'perfectpixel_last_login', true );
	return $time ? esc_html( wp_date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $time ) ) : 'Ποτέ';
}

function perfectpixel_last_login_sortable( $columns ) {
	$columns['perfectpixel_last_login'] = 'perfectpixel_last_login';
	return $columns;
}

function perfectpixel_last_login_orderby( $query ) {
	if ( is_admin() && 'perfectpixel_last_login' === $query->get( 'orderby' ) ) {
		$query->set( 'meta_key', 'perfectpixel_last_login' );
		$query->set( 'orderby', 'meta_value_num' );
	}
}
